def sprite_svg(nome: str, x: int, y: int, px: int, cor: str) -> str:
    partes = []
    linhas = SPRITES[nome]
    for ly, linha in enumerate(linhas):
        inicio = None
        for lx in range(len(linha) + 1):
            aceso = lx < len(linha) and linha[lx] == "#"
            if aceso and inicio is None:
                inicio = lx
            elif not aceso and inicio is not None:
                partes.append(
                    f'<rect x="{x + inicio * px}" y="{y + ly * px}" '
                    f'width="{(lx - inicio) * px}" height="{px}" fill="{cor}"/>'
                )
                inicio = None
    return "".join(partes)
